       }

       /// A sink over `state` that appends to the bench's events and draws from its rng.
       pub fn sink<'a>(&'a mut self, state: &'a mut GameState) -> EngineSink<'a> {
           EngineSink::new(state, &mut self.events, &mut self.rng)
